import React, { useState, useEffect } from "react";
import "bootstrap/dist/css/bootstrap.min.css";
import { useNavigate } from "react-router-dom";
import private_api from "../../server/private_api";

const LecionaLista = () => {
  const [cursos, setCursos] = useState([]);
  const [loading, setLoading] = useState(true);
  const navigate = useNavigate();

  // Obtém o ID do professor do localStorage (assumindo que está armazenado após login)
  const professorId = localStorage.getItem("userId");

  // Versão com logs para depuração (RECOMENDADA durante desenvolvimento)
  const fetchCursos = async () => {
    try {
      console.log(`Fetching cursos for professorId: ${professorId}`);
      const resposta = await private_api.get(
        `/professor/lecionalista/${professorId}`
      );
      console.log("Dados recebidos:", resposta.data);
      if (resposta.status === 200) {
        setCursos(resposta.data);
      } else {
        console.error("Erro ao buscar cursos");
      }
    } catch (error) {
      console.error("Erro na requisição:", error);
    } finally {
      setLoading(false);
    }
  };

  /* 
  // Versão original sem logs (para produção)
  const fetchCursos = async () => {
    try {
      const resposta = await private_api.get(`/professor/lecionalista/${professorId}`);
      if (resposta.status === 200) {
        setCursos(resposta.data);
      } else {
        console.error("Erro ao buscar cursos");
      }
    } catch (error) {
      console.error("Erro na requisição:", error);
    } finally {
      setLoading(false);
    }
  };
  */

  useEffect(() => {
    if (professorId) {
      fetchCursos();
    } else {
      setLoading(false);
      console.error("ID do professor não encontrado no localStorage");
    }
  }, [professorId]);

  if (loading) {
    return (
      <div className="d-flex justify-content-center mt-5">Carregando...</div>
    );
  }

  return (
    <div
      className="container-fluid d-flex flex-column align-items-center"
      style={{
        backgroundColor: "#E7EFF4",
        minHeight: "100vh",
        padding: "20px",
      }}
    >
      <nav className="nav nav-tabs mb-3 bg-white p-2 w-75 d-flex justify-content-center">
        <a className="nav-link active" href="#">
          Cursos
        </a>
        <a
          className="nav-link"
          href="#"
          onClick={() => navigate("/professoraulas")}
        >
          Aulas
        </a>
        <a
          className="nav-link"
          href="#"
          onClick={() => navigate("/professoravaliacoes")}
        >
          Avaliações
        </a>
      </nav>

      <h2 className="mb-3 text-center">Lista de Cursos à lecionar</h2>
      <table className="table table-bordered bg-white w-75">
        <thead>
          <tr>
            <th>Curso</th>
            <th>Nível</th>
            <th>Data de Início</th>
            <th>Data de Fim</th>
            <th>Período</th>
          </tr>
        </thead>
        <tbody>
          {cursos.length > 0 ? (
            cursos.map((curso) => (
              <tr key={curso.id}>
                <td>{curso.nome}</td>
                <td>{curso.nivel}</td>
                <td>{new Date(curso.dataInicio).toLocaleDateString()}</td>
                <td>{new Date(curso.dataFim).toLocaleDateString()}</td>
                <td>{curso.periodo}</td>
              </tr>
            ))
          ) : (
            <tr>
              <td colSpan="5" className="text-center">
                Nenhum curso encontrado
              </td>
            </tr>
          )}
        </tbody>
      </table>
    </div>
  );
};

export default LecionaLista;
